return ['domain'=>'nitrosearch','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'nb_NO','project-id-version'=>'NitroSearch for WooCommerce','pot-creation-date'=>'2026-08-15T09:09:15+00:00','po-revision-date'=>'2026-08-08 16:58+0000','messages'=>['NitroSearch for WooCommerce'=>'NitroSearch for WooCommerce','https://nitrosearch.io'=>'https://nitrosearch.io','Blazing-fast hosted search for WooCommerce. Syncs your catalog to NitroSearch and replaces the default WordPress search with instant, typo-tolerant results.'=>'Lynraskt, skybasert søk for WooCommerce. Synkroniserer katalogen din til NitroSearch og erstatter standardsøket i WordPress med umiddelbare resultater som tåler skrivefeil.','WebDeviant'=>'WebDeviant','https://webdeviant.io'=>'https://webdeviant.io','<strong>NitroSearch now measures how your store\'s search performs</strong> — anonymous, cookieless counts of searches and result clicks, with no shopper identifiers. It helps result ranking improve, and per-store reporting is on the roadmap.'=>'<strong>NitroSearch måler nå hvordan søket i butikken din presterer</strong> – anonyme tellinger av søk og resultatklikk, uten informasjonskapsler og uten identifikatorer for kundene. Det bidrar til bedre rangering av resultatene, og rapportering per butikk står på planen.','Manage it under %s.'=>'Du kan administrere dette under %s.','NitroSearch → Appearance'=>'NitroSearch → Utseende','Dismiss'=>'Avvis','Unauthorized.'=>'Ikke autorisert.','Not connected'=>'Ikke tilkoblet','Confirming control…'=>'Bekrefter kontroll …','Connected & verified'=>'Tilkoblet og bekreftet','Amazon-quality search for WooCommerce'=>'Søk i Amazon-klasse for WooCommerce','Connect your store'=>'Koble til butikken din','Connect this store to NitroSearch to start syncing your catalog and serving instant, typo-tolerant search. Nothing leaves your site until you click Connect.'=>'Koble denne butikken til NitroSearch for å begynne å synkronisere katalogen din og levere umiddelbart søk som tåler skrivefeil. Ingenting forlater nettstedet ditt før du klikker på Koble til.','Provisioning token'=>'Klargjøringstoken','Optional. Only needed if you were given a token to connect this store.'=>'Valgfritt. Trengs bare hvis du har fått et token for å koble til denne butikken.','Connect store'=>'Koble til butikk','Confirming control of your site…'=>'Bekrefter kontroll over nettstedet ditt …','We’re verifying that you control this store before building your search index. In production this is automatic; if your site isn’t reachable from our servers it can take a moment. Your catalog syncs as soon as it’s confirmed.'=>'Vi bekrefter at du har kontroll over denne butikken før vi bygger søkeindeksen din. På et nettsted i drift skjer dette automatisk; hvis nettstedet ditt ikke kan nås fra serverne våre, kan det ta en liten stund. Katalogen din synkroniseres så snart kontrollen er bekreftet.','Check status'=>'Sjekk status','Disconnect'=>'Koble fra','Dashboard'=>'Kontrollpanel','Design'=>'Design','You’ve reached your plan’s limit.'=>'Du har nådd grensen for planen din.','Your search keeps running for everything already indexed, but new items won’t be added until you upgrade. Your products always take priority, so anything held back is a page or a post. Open %s below to move to a bigger plan.'=>'Søket fortsetter å virke for alt som allerede er indeksert, men nye elementer legges ikke til før du oppgraderer. Produktene dine har alltid prioritet, så det som holdes tilbake, er en side eller et innlegg. Åpne %s nedenfor for å gå over til en større plan.','Manage / Upgrade'=>'Administrer / oppgrader','Sync health'=>'Synkroniseringsstatus','Search results indexed'=>'Indekserte søkeresultater','Unlimited'=>'Ubegrenset','Pending changes'=>'Ventende endringer','Last sync'=>'Siste synkronisering','Never'=>'Aldri','Last error'=>'Siste feil','Sync all products'=>'Synkroniser alle produkter','Refresh status'=>'Oppdater status','%s from now'=>'om %s','On demand'=>'Ved behov','unit: millisecondsms'=>'ms','Sync performance'=>'Synkroniseringsytelse','Avg sync speed'=>'Gj.sn. synkroniseringshastighet','Last batch'=>'Siste pulje','Items synced'=>'Elementer synkronisert','Batches sent'=>'Puljer sendt','Next sync'=>'Neste synkronisering','Changes to your catalog are batched and pushed in the background — these figures show how quickly they reach your search index.'=>'Endringer i katalogen din samles i puljer og sendes i bakgrunnen – disse tallene viser hvor raskt de når søkeindeksen din.','Search analytics'=>'Søkeanalyse','last 30 days'=>'siste 30 dager','Couldn’t load analytics just now — it will retry automatically.'=>'Kunne ikke laste inn analysen akkurat nå – den prøver igjen automatisk.','<strong>%1$s</strong> on your store in the last 30 days. See what shoppers searched for, what they clicked, and what they looked for and didn’t find — included on every paid plan, from %2$s.'=>'<strong>%1$s</strong> i butikken din de siste 30 dagene. Se hva kundene søkte etter, hva de klikket på, og hva de lette etter uten å finne – inkludert i alle betalte planer, fra %2$s.','%s search'=>'%s søk' . "\0" . '%s søk','%s/mo'=>'%s/mnd','Upgrade to unlock'=>'Oppgrader for å låse opp','Analytics starts collecting with plugin 1.5.0+ active — data appears within a few hours of shoppers searching.'=>'Analysen begynner å samle inn data når versjon 1.5.0 eller nyere av utvidelsen er aktiv – dataene vises innen noen timer etter at kundene har søkt.','Searches'=>'Søk','Zero-result rate'=>'Andel uten treff','Click-through'=>'Klikkandel','Top searches'=>'Toppsøk','Searched, found nothing'=>'Søkte, fant ingenting','View full analytics →'=>'Se hele analysen →','Your plan & account'=>'Din plan og konto','This store is claimed to a NitroSearch account. Manage your plan and billing from your NitroSearch dashboard.'=>'Denne butikken er knyttet til en NitroSearch-konto. Administrer planen din og faktureringen fra NitroSearch-kontrollpanelet ditt.','You\'re on the <strong>Free</strong> plan. Claim this store to a NitroSearch account to manage it or upgrade — your index and search stay exactly as they are.'=>'Du er på <strong>Gratis</strong>-planen. Knytt denne butikken til en NitroSearch-konto for å administrere den eller oppgradere – indeksen og søket ditt forblir akkurat som de er.','Roomy'=>'Romslig','Two-line names and a clear picture. The default.'=>'Produktnavn over to linjer og et tydelig bilde. Standardvalget.','Compact'=>'Kompakt','Smaller rows, so more products fit before scrolling.'=>'Mindre rader, så flere produkter får plass før du må rulle.','Big pictures'=>'Store bilder','Larger thumbnails for image-led catalogs.'=>'Større miniatyrbilder for kataloger der bildene er viktigst.','Text only'=>'Bare tekst','No pictures — good for spare parts and B2B.'=>'Ingen bilder – fint for reservedeler, komponenter og B2B.','Light'=>'Lys','A white panel. Suits most themes.'=>'Et hvitt panel. Passer de fleste temaer.','Dark'=>'Mørk','A dark panel, for dark headers and themes.'=>'Et mørkt panel, for mørke sidehoder og temaer.','Automatic'=>'Automatisk','Follows each shopper\'s own device setting.'=>'Følger enhetsinnstillingen til hver enkelt kunde.','Custom'=>'Egendefinert','Choose your own panel and text colors below.'=>'Velg dine egne panel- og tekstfarger nedenfor.','Look'=>'Utseende','Layout'=>'Oppsett','Products shown'=>'Produkter som vises','How many products appear in the drop-down as your shopper types.'=>'Hvor mange produkter som vises i nedtrekkspanelet mens kunden skriver.','Filters'=>'Filtre','Automatic (recommended)'=>'Automatisk (anbefalt)','Always across the top'=>'Alltid øverst','Hide in the drop-down'=>'Skjul i nedtrekkspanelet','In stock, on sale, brand and category filters. Automatic puts them in a side column when there is room, and across the top when there is not.'=>'Filtre for på lager, på tilbud, merke og kategori. Automatisk plasserer dem i en sidekolonne når det er plass, og øverst når det ikke er det.','Drop-down width'=>'Bredde på nedtrekkspanelet','Wide'=>'Bred','Match my search box'=>'Samme som søkefeltet mitt','Automatic gives product names enough room to read, even when your theme\'s search box is narrow. Match my search box keeps it exactly as wide as the box.'=>'Automatisk gir produktnavnene nok plass til å kunne leses, selv når søkefeltet i temaet ditt er smalt. Samme som søkefeltet mitt holder panelet nøyaktig like bredt som feltet.','Colors'=>'Farger','Color scheme'=>'Fargevalg','Accent color'=>'Aksentfarge','Used for prices, highlights and selected filters. Leave blank for the default. Text on top of it is set to black or white automatically, whichever stays readable.'=>'Brukes til priser, uthevinger og valgte filtre. La feltet stå tomt for standardfargen. Teksten oppå settes automatisk til svart eller hvit, alt etter hva som holder seg lesbart.','Panel background'=>'Panelbakgrunn','Only used when the color scheme is set to Custom.'=>'Brukes bare når fargevalget er satt til Egendefinert.','Text color'=>'Tekstfarge','Corners'=>'Hjørner','Rounded'=>'Avrundede','Slightly rounded'=>'Litt avrundede','Square'=>'Skarpe','Text style'=>'Skriftstil','Match my store'=>'Samme som butikken min','System default'=>'Systemstandard','Custom font'=>'Egendefinert skrift','Match my store borrows the font your theme already uses around the search box.'=>'Samme som butikken min låner skriften temaet ditt allerede bruker rundt søkefeltet.','example font stacke.g. Georgia, serif'=>'f.eks. Georgia, serif','Only used when Custom font is selected.'=>'Brukes bare når Egendefinert skrift er valgt.','What to search'=>'Hva søket skal omfatte','Include'=>'Inkluder','Products'=>'Produkter','always indexed'=>'indekseres alltid','Pages'=>'Sider','Blog posts'=>'Blogginnlegg','Pages and posts count toward the same allowance as your products, so switching them off frees it up for your catalog. Your products always come first and are never displaced by them. Private, password-protected and unpublished content is never indexed, and we honor %s set by Yoast SEO or Rank Math (per item, per content type, or site-wide).'=>'Sider og innlegg teller mot den samme kvoten som produktene dine, så slår du dem av, frigjør du plass til katalogen. Produktene dine kommer alltid først og fortrenges aldri av dem. Privat, passordbeskyttet og upublisert innhold indekseres aldri, og vi respekterer %s som er satt av Yoast SEO eller Rank Math (per element, per innholdstype eller for hele nettstedet).','Search results page'=>'Søkeresultatside','Enhance the product search results page with NitroSearch results and filters'=>'Forbedre søkeresultatsiden for produkter med resultater og filtre fra NitroSearch','Privacy &amp; credit'=>'Personvern og kreditering','Search usage data'=>'Søkebruksdata','Share anonymous search usage counts with NitroSearch'=>'Del anonyme tellinger av søkebruk med NitroSearch','Counts searches, result totals and result clicks on your store\'s search — cookieless and anonymous, with no shopper identifiers, no IP addresses and nothing stored in the shopper\'s browser. Used to improve result ranking and to power your search analytics. Uncheck to stop sending immediately.'=>'Teller søk, antall resultater og resultatklikk i butikkens søk – anonymt og uten informasjonskapsler, uten identifikatorer for kundene, uten IP-adresser og uten at noe lagres i kundens nettleser. Brukes til å forbedre rangeringen av resultatene og til å drive søkeanalysen din. Fjern avmerkingen for å stoppe sendingen umiddelbart.','Powered-by credit'=>'«Levert av»-kreditering','Show a small “Powered by NitroSearch” credit, linking to nitrosearch.io'=>'Vis en liten «Levert av NitroSearch»-kreditering med lenke til nitrosearch.io','Off by default, and entirely your choice. Turning it on adds a small credit in the search box and one line in your site footer, both linking to %s — a normal, followed link. Nothing is added to your site unless you check this. Thank you if you do.'=>'Av som standard, og helt opp til deg. Slår du den på, legges det til en liten kreditering i søkefeltet og én linje i bunnteksten på nettstedet ditt, begge med lenke til %s – en vanlig lenke som følges. Ingenting legges til på nettstedet ditt med mindre du merker av her. Tusen takk om du gjør det.','Advanced'=>'Avansert','Search box selector'=>'Velger for søkefeltet','example CSS selectore.g. input.my-theme-search'=>'f.eks. input.my-theme-search','Optional CSS selector for your theme\'s search input. Leave blank to auto-detect.'=>'Valgfri CSS-velger for søkefeltet i temaet ditt. La feltet stå tomt for automatisk gjenkjenning.','Save design'=>'Lagre design','Connect failed: %s'=>'Tilkoblingen mislyktes: %s','unknown error'=>'ukjent feil','Connected and verified.'=>'Tilkoblet og bekreftet.','Connected. Confirming control of your site — this can take a moment. Use “Check status” below if it doesn’t update.'=>'Tilkoblet. Bekrefter kontroll over nettstedet ditt – dette kan ta en liten stund. Bruk «Sjekk status» nedenfor hvis det ikke oppdaterer seg.','Syncing %s product in the background, then your pages and posts.'=>'Synkroniserer %s produkt i bakgrunnen, deretter sidene og innleggene dine.' . "\0" . 'Synkroniserer %s produkter i bakgrunnen, deretter sidene og innleggene dine.','Syncing %s product in the background.'=>'Synkroniserer %s produkt i bakgrunnen.' . "\0" . 'Synkroniserer %s produkter i bakgrunnen.','Verified!'=>'Bekreftet!','%1$s search results indexed · %2$s pending.'=>'%1$s søkeresultater indeksert · %2$s venter.','Still confirming control of your site — please try again in a moment.'=>'Bekrefter fremdeles kontroll over nettstedet ditt – prøv igjen om litt.','Design saved.'=>'Designet er lagret.','Saved. Removing your pages and blog posts from your index in the background.'=>'Lagret. Fjerner sidene og blogginnleggene dine fra indeksen i bakgrunnen.','Saved. Removing your pages from your index in the background.'=>'Lagret. Fjerner sidene dine fra indeksen i bakgrunnen.','Saved. Removing your blog posts from your index in the background.'=>'Lagret. Fjerner blogginnleggene dine fra indeksen i bakgrunnen.','Saved. Indexing your pages and blog posts in the background.'=>'Lagret. Indekserer sidene og blogginnleggene dine i bakgrunnen.','Saved. Indexing your pages in the background.'=>'Lagret. Indekserer sidene dine i bakgrunnen.','Saved. Indexing your blog posts in the background.'=>'Lagret. Indekserer blogginnleggene dine i bakgrunnen.','Disconnected.'=>'Frakoblet.','This store is already claimed to a NitroSearch account.'=>'Denne butikken er allerede knyttet til en NitroSearch-konto.','We couldn’t confirm control of your site yet — click "Refresh status" first, then try again.'=>'Vi fikk ikke bekreftet kontroll over nettstedet ditt ennå – klikk først på «Oppdater status», og prøv deretter igjen.','Your site needs re-checking — click "Refresh status", then try again.'=>'Nettstedet ditt må sjekkes på nytt – klikk på «Oppdater status», og prøv igjen.','Too many attempts — please wait a minute and try again.'=>'For mange forsøk – vent et minutt og prøv igjen.','Could not create a manage link. Please try again.'=>'Kunne ikke opprette en administrasjonslenke. Prøv igjen.','Insufficient permissions.'=>'Utilstrekkelige rettigheter.','Search powered by %s'=>'Søk levert av %s','Refine results'=>'Avgrens resultatene','Refine'=>'Avgrens','In stock'=>'På lager','On sale'=>'På tilbud','Brand'=>'Merke','Category'=>'Kategori','View'=>'Vis','Add to cart'=>'Legg i handlekurv','Adding…'=>'Legger til …','Added ✓'=>'Lagt til ✓','Try again'=>'Prøv igjen','Searching…'=>'Søker …','Search is unavailable.'=>'Søket er utilgjengelig.','Search is unavailable right now.'=>'Søket er utilgjengelig akkurat nå.','No products found.'=>'Fant ingen produkter.','No products found for “%s”.'=>'Fant ingen produkter for «%s».','Nothing found for “%s”.'=>'Fant ingenting for «%s».','Search products…'=>'Søk etter produkter …','Close search'=>'Lukk søket','Product results'=>'Produktresultater','Recent searches'=>'Nylige søk','Clear'=>'Tøm','Start typing to search products…'=>'Begynn å skrive for å søke etter produkter …','Sale'=>'Tilbud','Out of stock'=>'Ikke på lager','Pages & posts'=>'Sider og innlegg','a website page, shown on a search resultPage'=>'Side','a blog post, shown on a search resultArticle'=>'Artikkel','unit: milliseconds%s ms'=>'%s ms','Powered by %s'=>'Levert av %s','Page %1$s of %2$s'=>'Side %1$s av %2$s','← Prev'=>'← Forrige','Next →'=>'Neste →','button labelSearch'=>'Søk','%s product found.'=>'%s produkt funnet.' . "\0" . '%s produkter funnet.','See all %s result →'=>'Se %s resultat →' . "\0" . 'Se alle %s resultater →','%1$s result for “%2$s”'=>'%1$s resultat for «%2$s»' . "\0" . '%1$s resultater for «%2$s»','%s result'=>'%s resultat' . "\0" . '%s resultater']];